    throw new Error('Не удалось получить токен через Login: ' + e.message);
}

// create new booking
try {
    const bookingResponse = await pm.execution.runRequest('58305241-01b2fd84-ea09-40ce-a30e-06593a07cc01');
    pm.expect(bookingResponse.code).to.eq(200);
    const booking_id_new = bookingResponse.json().bookingid;
    pm.collectionVariables.set("booking_id_new", booking_id_new);
} catch (e) {
    throw new Error('Booking ID не получен ' + e.message);
}

// delete booking
const delBooking = pm.collectionVariables.get("HerokuApp") + "/booking/" + pm.collectionVariables.get("booking_id_new");
pm.sendRequest({
    url: delBooking,
    method: 'DELETE',
    header: {
        'Cookie': 'token=' + pm.collectionVariables.get("access_token")
    }
}, function (error, response) {
    if (response) {
        pm.expect(response.text()).to.equal("Created");
        console.log("Booking deleted successfully");
    }
    else {
        console.error('Error deleting booking:', error);
    }
});
